<?php
declare(strict_types=1);
require_once __DIR__ . '/../../config/config.php'; require_once ROOT_PATH . '/config/database.php'; require_once ROOT_PATH . '/modules/auth/guard.php'; require_role('admin');
$pdo=db(); $action=(string)($_POST['action']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{
    if($action==='teacher'){ $nama=trim((string)$_POST['nama']);$username=trim((string)$_POST['username']);if($nama===''||$username==='')throw new RuntimeException('Nama dan username guru wajib diisi.');$u=$pdo->prepare('INSERT INTO users (nama,username,email,password,role) VALUES (?,?,?,?,"guru")');$password=trim((string)($_POST['password']??'')) ?: 'guru123';$u->execute([$nama,$username,$username.'@guru.local',password_hash($password,PASSWORD_DEFAULT)]);$pdo->prepare('INSERT INTO teachers (user_id,nama,nip) VALUES (?,?,?)')->execute([(int)$pdo->lastInsertId(),$nama,trim((string)($_POST['nip']??''))]);}
    elseif($action==='subject'){ $nama=trim((string)$_POST['nama_mata_pelajaran']);if($nama==='')throw new RuntimeException('Nama mata pelajaran wajib diisi.');$pdo->prepare('INSERT INTO subjects (nama_mata_pelajaran) VALUES (?)')->execute([$nama]); }
    elseif($action==='schedule'){ $les=max(1,min(9,(int)$_POST['lesson_number']));$starts=['07:00:00','07:45:00','08:30:00','09:15:00','10:00:00','10:45:00','11:30:00','12:15:00','13:00:00'];$ends=['07:45:00','08:30:00','09:15:00','10:00:00','10:45:00','11:30:00','12:15:00','13:00:00','13:45:00'];$pdo->prepare('INSERT INTO schedules (teacher_id,class_id,subject_id,day,start_time,end_time,lesson_number,source_sheet) VALUES (?,?,?,?,?,?,?,"ADMIN")')->execute([(int)$_POST['teacher_id'],(int)$_POST['class_id'],(int)$_POST['subject_id'],(string)$_POST['day'],$starts[$les-1],$ends[$les-1],$les]);}
    set_flash_message('success','Data berhasil disimpan.'); redirect('modules/learning/admin.php');
}catch(Throwable $e){set_flash_message('danger',$e instanceof PDOException&&((int)$e->errorInfo[1]===1062)?'Data sudah ada.':$e->getMessage());}}
$teachers=$pdo->query('SELECT id,nama,nip FROM teachers ORDER BY nama')->fetchAll();$subjects=$pdo->query('SELECT id,nama_mata_pelajaran FROM subjects ORDER BY nama_mata_pelajaran')->fetchAll();$classes=$pdo->query('SELECT id,nama_kelas FROM classes ORDER BY nama_kelas')->fetchAll();$schedules=$pdo->query('SELECT sc.day,sc.lesson_number,sc.start_time,sc.end_time,t.nama,c.nama_kelas,s.nama_mata_pelajaran FROM schedules sc JOIN teachers t ON t.id=sc.teacher_id JOIN classes c ON c.id=sc.class_id JOIN subjects s ON s.id=sc.subject_id ORDER BY sc.day,sc.lesson_number LIMIT 300')->fetchAll();
$pageTitle='Guru & Jadwal';$activeMenu='learning_admin';require ROOT_PATH.'/include/header.php';require ROOT_PATH.'/include/navbar.php';require ROOT_PATH.'/include/sidebar.php';
?><main class="main-content"><div class="container-fluid p-3 p-md-4"><?php display_flash_message(); ?><h1 class="h3 fw-bold mb-1">Guru, Mata Pelajaran & Jadwal</h1><p class="text-secondary mb-4">Kelola data pembelajaran yang digunakan untuk membuka sesi absensi.</p><div class="row g-3"><div class="col-12 col-lg-4"><div class="card border-0 shadow-sm mb-3"><div class="card-header bg-white fw-bold">Tambah Guru</div><div class="card-body"><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="teacher"><input class="form-control mb-2" name="nama" placeholder="Nama guru" required><input class="form-control mb-2" name="nip" placeholder="NIP (opsional)"><input class="form-control mb-2" name="username" placeholder="Username" required><input class="form-control mb-3" name="password" placeholder="Password (default guru123)"><button class="btn btn-primary w-100">Simpan Guru</button></form></div></div><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold">Tambah Mata Pelajaran</div><div class="card-body"><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="subject"><div class="input-group"><input class="form-control" name="nama_mata_pelajaran" placeholder="Nama mata pelajaran" required><button class="btn btn-outline-primary">Tambah</button></div></form></div></div></div><div class="col-12 col-lg-8"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold">Tambah Jadwal</div><div class="card-body"><form method="post" class="row g-2"><?php csrf_field(); ?><input type="hidden" name="action" value="schedule"><div class="col-md-6"><select class="form-select" name="teacher_id" required><option value="">Pilih guru</option><?php foreach($teachers as $t):?><option value="<?=$t['id']?>"><?=e($t['nama'])?></option><?php endforeach;?></select></div><div class="col-md-6"><select class="form-select" name="class_id" required><option value="">Pilih kelas</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['nama_kelas'])?></option><?php endforeach;?></select></div><div class="col-md-6"><select class="form-select" name="subject_id" required><option value="">Pilih mata pelajaran</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['nama_mata_pelajaran'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="day"><?php foreach(['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'] as $d):?><option><?=$d?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="lesson_number"><?php for($i=1;$i<=9;$i++):?><option value="<?=$i?>">Les <?=$i?></option><?php endfor;?></select></div><div class="col-12"><button class="btn btn-primary">Simpan Jadwal</button></div></form></div></div><div class="card border-0 shadow-sm mt-3"><div class="card-header bg-white fw-bold">Jadwal Terdaftar (<?=count($schedules)?>)</div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Hari/Les</th><th>Guru</th><th>Kelas</th><th>Mata Pelajaran</th></tr></thead><tbody><?php foreach($schedules as $sc):?><tr><td><?=e($sc['day'])?> · <?=e($sc['lesson_number'])?><br><small><?=e(substr($sc['start_time'],0,5))?>–<?=e(substr($sc['end_time'],0,5))?></small></td><td><?=e($sc['nama'])?></td><td><?=e($sc['nama_kelas'])?></td><td><?=e($sc['nama_mata_pelajaran'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></main><?php require ROOT_PATH.'/include/footer.php'; ?>
